{
    var memberId = Convert.ToInt32(newJob.MemberId);
    var member = _context.Members.FirstOrDefault(m => m.Id == memberId);

    var offsetTimespan = member.TimezoneOffsetMinutes.HasValue
        ? TimeSpan.FromMinutes(member.TimezoneOffsetMinutes.Value)
        : Constants.DefaultTimezoneOffset;

    var dayBegin = Constants.WorkdayBeginUtc - offsetTimespan;
    var dayEnd = Constants.WorkdayEndUtc - offsetTimespan;

    var jobs = _context.Jobs
        .Where(j => j.MemberId == newJob.MemberId)
        .Where(j => j.start.HasValue && j.end.HasValue)
        .Where(j => !j.Finished.HasValue || !j.Finished.Value)
        .OrderBy(j => j.start)
        .ToList();


    var startDate = finishedJob.ActualEnd ?? DateTime.Now;
    newJob.Deadline = CalculateDeadlineDate(startDate, nextStage.Deadline.Value, nextStage.DeadlineUnit, offsetTimespan);

    while (true)
    {
        var endDate = startDate + TimeSpan.FromMinutes(nextStage.DurationMinutes.Value);
        var overlappingJobs = jobs.Where(j => j.start <= endDate && j.end >= startDate).ToList();
        if (!overlappingJobs.Any() && endDate.TimeOfDay < dayEnd)
        {
            newJob.start = startDate;
            newJob.end = endDate;
            return;
        }

        if (overlappingJobs.Any())
        {
            startDate = overlappingJobs.Select(j => j.end).Max().Value;
        }
        else
        {
            startDate = startDate.AddBusinessDays(1).Date + dayBegin;
        }

    }


}

